window.kbPageData["views/entry/k-e215c10238357d28"] = {"key":"entry/k-e215c10238357d28","state":{"route":"entry/k-e215c10238357d28"},"node":{"id":"k-e215c10238357d28","mode":"k","title":"互异正整数的和上界","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["最大值受限时互异正整数的和上界"],"qs":["江苏 2025 C类 行测#67"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"若 k 个互不相同的正整数都不超过整数 x，且 x≥k，则它们的和最多为 x+(x−1)+⋯+(x−k+1)，由最大的 k 个可取整数达到。","review":{"definition":"若 k 个互不相同的正整数都不超过整数 x，且 x≥k，则它们的和最多为 x+(x−1)+⋯+(x−k+1)，由最大的 k 个可取整数达到。","explanation":"设按每束9枝可扎 b 束。由总枝数除以8余3、除以9余5，得到9b+2是8的倍数，故 b 除以8余6，总枝数至少为59。若三束中最多的一束只有20枝，三束互异时总数至多为20+19+18=57。59枝可以分成21、20、18枝，所以最多的一束至少有21枝。","references":[],"evidence":"制成数量各不相同的3束玫瑰花","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2025 C类 行测#67":{"paper":"江苏 2025 C类 行测","n":67,"mod":"数量关系","src":["ffc394a1c160f331ec57.pdf",14],"asrc":["d1de3b437151c05b769e.pdf",20],"card":"31f03f87567adcfef654d6d0","links":[{"id":"k-e215c10238357d28","role":"解题依据","why":"最大一项为 x 时，三个互异正整数的和至多为 x、x−1、x−2 之和，据此可约束最大项的下界。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-e215c10238357d28":[["江苏 2025 C类 行测#67"]]}};
